1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code householdMemberCount}: the number of owners in the new owner's
9	 * household <em>after</em> this create, i.e. the existing members sharing its {@code householdId}
10	 * plus the new owner itself.
11	 *
12	 * <p>Runs after {@link AssignHousehold} (which sets the shared {@code householdId} when the request
13	 * opts in and joins an existing household) and before {@link SaveOwner}, so the existing members are
14	 * already carrying the id but the new owner is not yet persisted — hence the {@code + 1}. When the
15	 * owner does not join a household ({@code householdId} is {@code null}), it is the sole member and
16	 * the count is {@code 1}.
17	 *
18	 * <p>The count is what drives the {@code GOLD} membership tier (3 or more members); see
19	 * {@link org.springframework.samples.petclinic.mapper.OwnerMapper}.
20	 */
21	public class AssignHouseholdSize {
22	
23	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
24	        String householdId = owner.getHouseholdId();
25	        int count = 1;
26	        if (householdId != null) {
27	            for (Owner existing : ownerRepository.findAll()) {
28	                if (householdId.equals(existing.getHouseholdId())) {
29	                    count++;
30	                }
31	            }
32	        }
33	        owner.setHouseholdMemberCount(count);
34	    }
35	}
