2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of existing owners that already share the
9	 * new owner's {@code firstName} and {@code lastName}, compared case-insensitively.
10	 *
11	 * <p>Runs before {@link SaveOwner}, so the count reflects the owners already persisted (i.e. the
12	 * value before this create) and the new owner itself is not counted.
13	 */
14	public class AssignNamesakeCount {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String firstName = owner.getFirstName();
18	        String lastName = owner.getLastName();
19	        int count = 0;
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (equalsIgnoreCase(firstName, existing.getFirstName())
22	                    && equalsIgnoreCase(lastName, existing.getLastName())) {
23	                count++;
24	            }
25	        }
26	        owner.setNamesakeCount(count);
27	    }
28	
29	    private static boolean equalsIgnoreCase(String a, String b) {
30	        return a == null ? b == null : a.equalsIgnoreCase(b);
31	    }
32	}
